  7	use crate::daemon::{Daemon, ProjectInfo, SessionSummary};
  8	use crate::search::fuzzy_score;
  9	#[cfg(target_arch = "wasm32")]
 10	use crate::sessions::is_recent;
 11	use crate::sessions::{fmt_relative_time, project_for_root, session_root, split_origin};
 12	
 13	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 14	pub enum IslandMode {
 15	    Closed,
 16	    Browse,
 17	    Search,
 18	}
 19	
 20	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
 21	pub enum IslandPriority {
 22	    Focused,
 23	    Recent,
 24	    Background,
 25	}
 26	
 27	#[derive(Clone, Debug, PartialEq)]
 28	pub struct IslandSession {
 29	    pub id: String,
 30	    pub title: String,
 31	    pub project: Option<String>,
 32	    pub cwd: String,
 33	    pub branch: Option<String>,
 34	    pub origin: Option<String>,
 35	    pub updated_at: String,
 36	    pub turn_count: u32,
 37	    pub is_focused: bool,
 38	    pub priority: IslandPriority,
 39	}
 40	
 41	#[derive(Clone, Debug, PartialEq)]
 42	pub enum IslandResult {
 43	    Session(IslandSession),
 44	}
 45	
 46	fn recently_updated(updated_at: &str) -> bool {
 47	    #[cfg(target_arch = "wasm32")]
 48	    {
 49	        is_recent(updated_at)
 50	    }
 51	    #[cfg(not(target_arch = "wasm32"))]
 52	    {
 53	        // Browser time is intentionally unavailable in native unit tests.
 54	        // Sorting remains fully deterministic there; production uses the
 55	        // shared sessions-panel recency window above.
 56	        let _ = updated_at;
 57	        false
 58	    }
 59	}
 60	
 61	/// Project daemon sessions into the compact metadata used by the Island.
 62	pub(crate) fn derive_island_sessions(
 63	    sessions: &[SessionSummary],
 64	    projects: &[ProjectInfo],
 65	    focused_id: Option<&str>,
 66	) -> Vec<IslandSession> {
 67	    let mut items: Vec<_> = sessions
 68	        .iter()
 69	        .map(|session| {
 70	            let root = session_root(session).to_string();
 71	            let project = session
 72	                .owning_project
 73	                .as_ref()
 74	                .map(|owner| {
 75	                    if owner.name.trim().is_empty() {
 76	                        owner.id.clone()
 77	                    } else {
 78	                        owner.name.trim().to_string()
 79	                    }
 80	                })
 81	                .or_else(|| {
 82	                    project_for_root(projects, &root).map(|project| {
 83	                        if project.name.trim().is_empty() {
 84	                            project.id.clone()
 85	                        } else {
 86	                            project.name.trim().to_string()
 87	                        }
 88	                    })
 89	                });
 90	            let (origin, title) = split_origin(&session.title);
 91	            let is_focused = focused_id == Some(session.id.as_str());
 92	            let priority = if is_focused {
 93	                IslandPriority::Focused
 94	            } else if recently_updated(&session.updated_at) {
 95	                IslandPriority::Recent
 96	            } else {
 97	                IslandPriority::Background
 98	            };
 99	
100	            IslandSession {
101	                id: session.id.clone(),
102	                title,
103	                project,
104	                cwd: root,
105	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
106	                origin,
107	                updated_at: session.updated_at.clone(),
108	                turn_count: session.turn_count,
109	                is_focused,
110	                priority,
111	            }
112	        })
113	        .collect();
114	
115	    items.sort_by(|a, b| {
116	        b.is_focused
117	            .cmp(&a.is_focused)
118	            .then_with(|| b.updated_at.cmp(&a.updated_at))
119	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
120	            .then_with(|| a.id.cmp(&b.id))
121	    });
122	    items
123	}
124	
125	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
126	pub(crate) fn island_search_text(item: &IslandSession) -> String {
127	    let state = match item.priority {
128	        IslandPriority::Focused => "focused",
129	        IslandPriority::Recent => "recent",
130	        IslandPriority::Background => "background",
131	    };
132	    let project = item.project.as_deref().unwrap_or_default();
133	    let branch = item.branch.as_deref().unwrap_or_default();
134	    let origin = item.origin.as_deref().unwrap_or_default();
135	    format!(
136	        "{} {} project:{} {} {} {} {} {} turns",
137	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
138	    )
139	    .to_lowercase()
140	}
141	
142	/// Search the Island corpus while preserving derivation order for an empty
143	/// query and using focus/recency only as small tie-breaks for real queries.
144	pub(crate) fn search_island(query: &str, items: &[IslandSession]) -> Vec<IslandResult> {
145	    let query = query.trim();
146	    if query.is_empty() {
147	        return items.iter().cloned().map(IslandResult::Session).collect();
148	    }
149	
150	    let query_lower = query.to_lowercase();
151	    let mut scored: Vec<(u8, f64, usize, IslandSession)> = items
152	        .iter()
153	        .enumerate()
154	        .filter_map(|(index, item)| {
155	            let document_score = fuzzy_score(query, &island_search_text(item))?;
156	            let title = item.title.to_lowercase();
157	            let title_score = fuzzy_score(query, &item.title);
158	            let project = item.project.as_deref().map(str::to_lowercase);
159	            let project_score = project
160	                .as_deref()
161	                .and_then(|project| fuzzy_score(query, project));
162	
163	            // Match category is a strict tier; fuzzy score only orders items
164	            // inside a tier, so a long fuzzy title can never outrank an exact
165	            // project (and metadata can never outrank a title/project match).
166	            let (tier, mut score) = if title == query_lower {
167	                (6, title_score.unwrap_or(document_score))
168	            } else if title.starts_with(&query_lower) {
169	                (5, title_score.unwrap_or(document_score))
170	            } else if project.as_deref() == Some(query_lower.as_str()) {
171	                (4, project_score.unwrap_or(document_score))
172	            } else if project
173	                .as_deref()
174	                .is_some_and(|project| project.starts_with(&query_lower))
175	            {
176	                (3, project_score.unwrap_or(document_score))
177	            } else if let Some(title_score) = title_score {
178	                (2, title_score)
179	            } else if let Some(project_score) = project_score {
180	                (1, project_score)
181	            } else {
182	                (0, document_score)
183	            };
184	            score += match item.priority {
185	                IslandPriority::Focused => 2.0,
186	                IslandPriority::Recent => 1.0,
187	                IslandPriority::Background => 0.0,
188	            };
189	            Some((tier, score, index, item.clone()))
190	        })
191	        .collect();
192	
193	    scored.sort_by(|a, b| {
194	        b.0.cmp(&a.0)
195	            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
196	            .then_with(|| a.2.cmp(&b.2))
197	            .then_with(|| a.3.id.cmp(&b.3.id))
198	    });
199	    scored
200	        .into_iter()
201	        .map(|(_, _, _, item)| IslandResult::Session(item))
202	        .collect()
203	}
204	
205	fn option_id(session_id: &str) -> String {
206	    let encoded = session_id
207	        .as_bytes()
208	        .iter()
209	        .map(|byte| format!("{byte:02x}"))
210	        .collect::<String>();
211	    format!("island-option-{encoded}")
212	}
213	
214	fn next_index(index: usize, len: usize) -> usize {
215	    if len == 0 {
216	        0
217	    } else {
218	        (index + 1) % len
219	    }
220	}
221	
222	fn previous_index(index: usize, len: usize) -> usize {
223	    if len == 0 {
224	        0
225	    } else {
226	        (index + len - 1) % len
227	    }
228	}
