230	#[component]
231	pub fn Island(
232	    daemon: Daemon,
233	    mode: RwSignal<IslandMode>,
234	    focus_request: RwSignal<u64>,
235	    on_open: Callback<IslandMode>,
236	) -> impl IntoView {
237	    let query = RwSignal::new(String::new());
238	    let selected_index = RwSignal::new(0usize);
239	    let previous_mode = RwSignal::new(IslandMode::Closed);
240	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
241	    let last_focus_request = RwSignal::new(0u64);
242	    let recency_tick = RwSignal::new(0u64);
243	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
244	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
245	
246	    #[cfg(target_arch = "wasm32")]
247	    let recency_interval =
248	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(60_000, move || {
249	            recency_tick.update(|tick| *tick = tick.wrapping_add(1))
250	        }));
251	    #[cfg(target_arch = "wasm32")]
252	    on_cleanup(move || drop(recency_interval));
253	
254	    let session_list = daemon.session_list;
255	    let projects = daemon.projects;
256	    let focused_id = daemon.session_id;
257	    let daemon = StoredValue::new(daemon);
258	
259	    let sessions = Memo::new(move |_| {
260	        let _ = recency_tick.get();
261	        derive_island_sessions(
262	            &session_list.get(),
263	            &projects.get(),
264	            focused_id.get().as_deref(),
265	        )
266	    });
267	    let results = Memo::new(move |_| {
268	        let mut matches = search_island(&query.get(), &sessions.get());
269	        if mode.get() == IslandMode::Search {
270	            matches.truncate(20);
271	        }
272	        matches
273	    });
274	
275	    Effect::new(move |_| {
276	        let next = mode.get();
277	        let request = focus_request.get();
278	        let previous = previous_mode.get_untracked();
279	        let previous_request = last_focus_request.get_untracked();
280	        if next != IslandMode::Closed && previous == IslandMode::Closed {
281	            let active = web_sys::window()
282	                .and_then(|window| window.document())
283	                .and_then(|document| document.active_element())
284	                .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok());
285	            previous_focus.set_value(active);
286	            query.set(String::new());
287	            selected_index.set(0);
288	            let daemon = daemon.get_value();
289	            daemon.fetch_sessions();
290	            daemon.fetch_projects();
291	        }
292	        let should_focus = next != IslandMode::Closed
293	            && (previous == IslandMode::Closed || next != previous || request != previous_request);
294	        if should_focus {
295	            request_animation_frame(move || {
296	                if let Some(input) = input_ref.get() {
297	                    let _ = input.focus();
298	                    if next == IslandMode::Search {
299	                        input.select();
300	                    }
301	                }
302	            });
303	        } else if next == IslandMode::Closed && previous != IslandMode::Closed {
304	            request_animation_frame(move || {
305	                if let Some(element) = previous_focus.get_value().filter(|el| el.is_connected()) {
306	                    let _ = element.focus();
307	                } else if let Some(chip) = chip_ref.get() {
308	                    let _ = chip.focus();
309	                }
310	            });
311	        }
312	        previous_mode.set(next);
313	        last_focus_request.set(request);
314	    });
315	
316	    Effect::new(move |_| {
317	        let len = results.get().len();
318	        if len == 0 || selected_index.get() >= len {
319	            selected_index.set(0);
320	        }
321	    });
322	
323	    let selected_option_id = move || {
324	        results
325	            .get()
326	            .get(selected_index.get())
327	            .map(|result| match result {
328	                IslandResult::Session(item) => option_id(&item.id),
329	            })
330	            .unwrap_or_default()
331	    };
332	    let close = move || mode.set(IslandMode::Closed);
333	    let on_keydown = move |event: KeyboardEvent| {
334	        if mode.get_untracked() == IslandMode::Closed || event.is_composing() {
335	            return;
336	        }
337	        let len = results.get_untracked().len();
338	        match event.key().as_str() {
339	            "Escape" => {
340	                event.prevent_default();
341	                event.stop_propagation();
342	                close();
343	            }
344	            "ArrowDown" => {
345	                event.prevent_default();
346	                selected_index.update(|index| *index = next_index(*index, len));
347	            }
348	            "ArrowUp" => {
349	                event.prevent_default();
350	                selected_index.update(|index| *index = previous_index(*index, len));
351	            }
352	            "Enter" => {
353	                event.prevent_default();
354	                if let Some(IslandResult::Session(item)) =
355	                    results.get_untracked().get(selected_index.get_untracked())
356	                {
357	                    daemon
358	                        .get_value()
359	                        .switch_session(item.id.clone(), item.title.clone());
360	                    close();
361	                }
362	            }
363	            "Tab" => {
364	                // The dialog uses an active-descendant combobox: DOM focus
365	                // remains on its one tabbable control while arrows move the
366	                // announced listbox option.
367	                event.prevent_default();
368	                if let Some(input) = input_ref.get() {
369	                    let _ = input.focus();
370	                }
371	            }
372	            _ => {}
373	        }
374	    };
375	
376	    let focused_session = Memo::new(move |_| {
377	        sessions
378	            .get()
379	            .into_iter()
380	            .find(|session| session.is_focused)
381	    });
382	    let recent_count = Memo::new(move |_| {
383	        sessions
384	            .get()
385	            .iter()
386	            .filter(|session| !session.is_focused && session.priority == IslandPriority::Recent)
387	            .count()
388	    });
389	    let chip_label = move || {
390	        focused_session.get().map_or_else(
391	            || "Ocean, no focused session. Open session browser".to_string(),
392	            |session| {
393	                let project = session
394	                    .project
395	                    .as_deref()
396	                    .map(|value| format!(", {value}"))
397	                    .unwrap_or_default();
398	                format!(
399	                    "Focused session: {}{}. {} recent sessions. Open session browser",
400	                    session.title,
401	                    project,
402	                    recent_count.get()
