 27	#[derive(Clone, Debug, PartialEq)]
 28	pub struct IslandSession {
 29	    pub id: String,
 30	    pub title: String,
 31	    pub project: Option<String>,
 32	    pub cwd: String,
 33	    pub branch: Option<String>,
 34	    pub origin: Option<String>,
 35	    pub updated_at: String,
