 46	fn recently_updated(updated_at: &str) -> bool {
 47	    #[cfg(target_arch = "wasm32")]
 48	    {
 49	        is_recent(updated_at)
 50	    }
 51	    #[cfg(not(target_arch = "wasm32"))]
 52	    {
 53	        // Browser time is intentionally unavailable in native unit tests.
 54	        // Sorting remains fully deterministic there; production uses the
 55	        // shared sessions-panel recency window above.
 56	        let _ = updated_at;
 57	        false
 58	    }
