 61	/// Project daemon sessions into the compact metadata used by the Island.
 62	pub(crate) fn derive_island_sessions(
 63	    sessions: &[SessionSummary],
 64	    projects: &[ProjectInfo],
 65	    focused_id: Option<&str>,
 66	) -> Vec<IslandSession> {
 67	    let mut items: Vec<_> = sessions
 68	        .iter()
 69	        .map(|session| {
 70	            let root = session_root(session).to_string();
 71	            let project = session
 72	                .owning_project
 73	                .as_ref()
 74	                .map(|owner| {
 75	                    if owner.name.trim().is_empty() {
 76	                        owner.id.clone()
 77	                    } else {
 78	                        owner.name.trim().to_string()
 79	                    }
 80	                })
 81	                .or_else(|| {
 82	                    project_for_root(projects, &root).map(|project| {
 83	                        if project.name.trim().is_empty() {
 84	                            project.id.clone()
 85	                        } else {
 86	                            project.name.trim().to_string()
 87	                        }
 88	                    })
 89	                });
 90	            let (origin, title) = split_origin(&session.title);
 91	            let is_focused = focused_id == Some(session.id.as_str());
 92	            let priority = if is_focused {
 93	                IslandPriority::Focused
 94	            } else if recently_updated(&session.updated_at) {
 95	                IslandPriority::Recent
 96	            } else {
 97	                IslandPriority::Background
 98	            };
 99	
100	            IslandSession {
101	                id: session.id.clone(),
102	                title,
103	                project,
104	                cwd: root,
105	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
106	                origin,
107	                updated_at: session.updated_at.clone(),
108	                turn_count: session.turn_count,
109	                is_focused,
110	                priority,
111	            }
112	        })
113	        .collect();
114	
115	    items.sort_by(|a, b| {
116	        b.is_focused
117	            .cmp(&a.is_focused)
118	            .then_with(|| b.updated_at.cmp(&a.updated_at))
119	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
120	            .then_with(|| a.id.cmp(&b.id))
121	    });
122	    items
123	}
