125	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
126	pub(crate) fn island_search_text(item: &IslandSession) -> String {
127	    let state = match item.priority {
128	        IslandPriority::Focused => "focused",
129	        IslandPriority::Recent => "recent",
130	        IslandPriority::Background => "background",
131	    };
132	    let project = item.project.as_deref().unwrap_or_default();
133	    let branch = item.branch.as_deref().unwrap_or_default();
134	    let origin = item.origin.as_deref().unwrap_or_default();
135	    format!(
136	        "{} {} project:{} {} {} {} {} {} turns",
137	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
138	    )
139	    .to_lowercase()
140	}
