content.text:
     1	/* Dynamic Island — native titlebar session focus/search. Tauri-only in the
     2	   component tree; these selectors remain inert on web and extension hosts. */
     3	
     4	:root {
     5	  --island-max-w: 360px;
     6	  --island-popover-w: min(560px, calc(100vw - 32px));
     7	  --island-top: 64px;
     8	}
     9	
    10	.ocean-header {
    11	  position: relative;
    12	}
    13	
    14	.ocean-header__left {
    15	  display: flex;
    16	  align-items: center;
    17	  min-width: 0;
    18	}
    19	
    20	/* Center inside the real header/content column without transform. Fixed
    21	   descendants therefore stay viewport-fixed instead of inheriting a new
    22	   containing block. The percentage cap reserves both titlebar control zones. */
    23	.island-host {
    24	  position: absolute;
    25	  inset-inline: 0;
    26	  top: 11px;
    27	  width: min(var(--island-max-w), 44%);
    28	  height: var(--ctl-h);
    29	  margin-inline: auto;
    30	  z-index: 122;
    31	}
    32	
    33	.island-chip {
    34	  position: relative;
    35	  z-index: 122;
    36	  display: flex;
    37	  align-items: center;
    38	  gap: 7px;
    39	  width: 100%;
    40	  height: var(--ctl-h);
    41	  min-width: 0;
    42	  padding: 0 12px;
    43	  border: 0;
    44	  border-radius: var(--radius);
    45	  background: var(--ocean-2);
    46	  box-shadow: var(--elev-1);
    47	  color: var(--fg);
    48	  font: 500 12px/1 var(--font);
    49	  cursor: pointer;
    50	  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
    51	}
    52	
    53	.island-chip:hover,
    54	.island-chip[aria-expanded="true"] {
    55	  background: var(--ocean-3);
    56	}
    57	
    58	.island-chip:focus-visible {
    59	  box-shadow: var(--elev-1), var(--focus-ring);
    60	}
    61	
    62	.island-chip__dot {
    63	  width: 7px;
    64	  height: 7px;
    65	  flex: 0 0 7px;
    66	  border-radius: var(--radius-pill);
    67	  background: var(--accent-bright);
    68	}
    69	
    70	.island-chip__title,
    71	.island-chip__project,
    72	.island-chip__count {
    73	  min-width: 0;
    74	  overflow: hidden;
    75	  text-overflow: ellipsis;
    76	  white-space: nowrap;
    77	}
    78	
    79	.island-chip__title {
    80	  flex: 1 1 auto;
    81	  text-align: left;
    82	}
    83	
    84	.island-chip__project {
    85	  flex: 0 1 auto;
    86	  color: var(--fg-2);
    87	}
    88	
    89	.island-chip__count,
    90	.island-chip__separator {
    91	  flex: 0 0 auto;
    92	  color: var(--fg-2);
    93	}
    94	
    95	.island-scrim {
    96	  position: fixed;
    97	  inset: 0;
    98	  z-index: 120;
    99	  background: color-mix(in srgb, var(--bg) 68%, transparent);
   100	}
   101	
   102	/* Left/right auto margins center the fixed surface in the usable content
   103	   viewport. No transform is used, so opening motion can never displace it. */
   104	.island-popover {
   105	  position: fixed;
   106	  top: var(--island-top);
   107	  left: 16px;
   108	  right: 16px;
   109	  z-index: 121;
   110	  width: var(--island-popover-w);
   111	  max-height: min(620px, calc(100vh - var(--island-top) - 16px));
   112	  margin-inline: auto;
   113	  display: flex;
   114	  flex-direction: column;
   115	  padding: 4px;
   116	  border-radius: var(--radius-lg);
   117	  background: var(--sheen), var(--bg-raised);
   118	  box-shadow: var(--elev-3);
   119	  overflow: hidden;
   120	}
   121	
   122	/* When the workspace splits the desktop, align the popover to the same
   123	   remaining content/header center instead of the full window center. */
   124	@media (min-width: 900px) {
   125	  .has-workspace-open .island-popover {
   126	    right: calc(var(--workspace-w) + 16px);
   127	    width: min(560px, calc(100vw - var(--workspace-w) - 32px));
   128	  }
   129	}
   130	
   131	.island-search {
   132	  flex: 0 0 auto;
   133	  border-radius: var(--radius);
   134	  background: var(--bg-elevated);
   135	  box-shadow: var(--well);
   136	}
   137	
   138	.island-search__input {
   139	  appearance: none;
   140	  display: block;
   141	  width: 100%;
   142	  min-height: 40px;
   143	  padding: 10px 12px;
   144	  border: 0;
   145	  border-radius: var(--radius);
   146	  outline: 0;
   147	  background: transparent;
   148	  color: var(--fg);
   149	  caret-color: var(--accent);
   150	  font: 400 13px/1.4 var(--font);
   151	}
   152	
   153	.island-search__input::placeholder {
   154	  color: var(--fg-3);
   155	}
   156	
   157	.island-search__input:focus-visible {
   158	  box-shadow: var(--focus-ring);
   159	}
   160	
   161	.island-results {
   162	  min-height: 0;
   163	  max-height: min(464px, calc(100vh - var(--island-top) - 72px));
   164	  overflow-y: auto;
   165	  padding: 4px 0 0;
   166	  border-radius: var(--radius);
   167	}
   168	
   169	.island-group {
   170	  display: flex;
   171	  flex-direction: column;
   172	}
   173	
   174	.island-result {
   175	  appearance: none;
   176	  width: 100%;
   177	  min-width: 0;
   178	  padding: 10px 12px;
   179	  border: 0;
   180	  border-radius: var(--radius);
   181	  background: transparent;
   182	  color: var(--fg-2);
   183	  text-align: left;
   184	  cursor: pointer;
   185	  transition: background var(--dur-fast) var(--ease);
   186	}
   187	
   188	.island-result:hover,
   189	.island-result--selected {
   190	  background: var(--bg-hover);
   191	}
   192	
   193	.island-result:focus-visible {
   194	  box-shadow: var(--focus-ring);
   195	}
   196	
   197	.island-result__primary,
   198	.island-result__meta {
   199	  display: flex;
   200	  align-items: center;
   201	  min-width: 0;
   202	}
   203	
   204	.island-result__primary {
   205	  gap: 8px;
   206	}
   207	
   208	.island-result__title {
   209	  min-width: 0;
   210	  overflow: hidden;
   211	  text-overflow: ellipsis;
   212	  white-space: nowrap;
   213	  color: var(--fg);
   214	  font: 500 13px/1.35 var(--font);
   215	}
   216	
   217	.island-result__focused {
   218	  flex: 0 0 auto;
   219	  padding: 2px 5px;
   220	  border-radius: var(--radius-sm);
   221	  background: var(--accent-soft);
   222	  color: var(--accent-bright);
   223	  font: 600 9px/1.3 var(--font);
   224	  letter-spacing: 0.04em;
   225	  text-transform: uppercase;
   226	}
   227	
   228	.island-result__meta {
   229	  gap: 0;
   230	  margin-top: 3px;
   231	  color: var(--fg-3);
   232	  font: 400 10px/1.4 var(--font);
   233	  white-space: nowrap;
   234	  overflow: hidden;
   235	}
   236	
   237	.island-result__meta > span {
   238	  min-width: 0;
   239	  max-width: 18ch;
   240	  overflow: hidden;
   241	  text-overflow: ellipsis;
   242	}
   243	
   244	.island-result__meta > span:empty {
   245	  display: none;
   246	}
   247	
   248	.island-result__meta > span + span:not(:empty)::before {
   249	  content: "·";
   250	  padding: 0 5px;
   251	  color: var(--fg-4);
   252	}
   253	
   254	.island-result__path {
   255	  font-family: var(--mono);
   256	}
   257	
   258	.island-empty {
   259	  padding: 28px 16px;
   260	  color: var(--fg-3);
   261	  font: 400 12px/1.4 var(--font);
   262	  text-align: center;
   263	}
   264	
   265	/* The workspace becomes a split column at 900px and may consume up to 65%
   266	   of the window. Keep the remaining header to the identity dot/state dots so
   267	   the centered Island has stable reserved tracks even at that maximum. */
   268	@media (min-width: 900px) {
   269	  .has-workspace-open .ocean-brand__word,
   270	  .has-workspace-open .ocean-tokens,
   271	  .has-workspace-open .ocean-status__text,
   272	  .has-workspace-open .ocean-browser-control__label {
   273	    display: none;
   274	  }
   275	}
   276	
   277	@media (min-width: 900px) and (max-width: 1100px) {
   278	  .has-workspace-open .ocean-brand {
   279	    display: none;
   280	  }
   281	}
   282	
   283	@media (max-width: 1000px) {
   284	  .island-host {
   285	    width: min(300px, 42%);
   286	  }
   287	
   288	  .island-chip__project,
   289	  .island-chip__separator {
   290	    display: none;
   291	  }
   292	}
   293	
   294	@media (max-width: 840px) {
   295	  .is-titlebar .ocean-brand__word {
   296	    display: none;
   297	  }
   298	
   299	  .island-host {
   300	    width: min(240px, 38%);
   301	  }
   302	
   303	  .island-chip {
   304	    padding-inline: 9px;
   305	  }
   306	
   307	  .island-chip__count {
   308	    max-width: 7ch;
   309	  }
   310	}
   311	
   312	@media (max-width: 720px) {
   313	  /* compact.css is later in the cascade; this higher-specificity titlebar
   314	     rule keeps the native traffic-light inset at the supported minimum. */
   315	  main.ocean-surface.is-titlebar .ocean-header {
   316	    padding-left: var(--titlebar-inset);
   317	  }
   318	
   319	  .island-host {
   320	    width: min(210px, 36%);
   321	  }
   322	
   323	  .island-chip__count {
   324	    display: none;
   325	  }
   326	}
   327	
   328	@media (prefers-reduced-motion: reduce) {
   329	  .island-chip,
   330	  .island-result {
   331	    transition: none;
   332	  }
   333	}

