text:
  1	/* Workspace pane — the permanent RIGHT-side desktop shell pane
  2	   (docs/OCEAN_DESKTOP_NORTH_STAR.md). Tauri-only: the component never mounts
  3	   on the browser PWA or Chrome extension, so these rules are inert there.
  4	   Colors come ONLY from tokens.css variables. Material rule (same as
  5	   deck.css): an element takes the border recipe OR the elevation recipe,
  6	   never both.
  7	
  8	   z-index ladder (right-side surfaces):
  9	     .workspace ........ 50  (permanent pane; above content, below reveals)
 10	     .deck ............. 60  (transient reveal-on-intent rail)
 11	     modals (panels) ... 100
 12	     palette overlay ... 1100
 13	   The workspace sits ABOVE the in-flow transcript/composer (z auto) so it can
 14	   overlay on compact widths, and BELOW the deck + palette so transient
 15	   reveals win. */
 16	
 17	/* The pane width is shared by the pane itself and the layout gutter the app
 18	   shell carves out of <main> when the pane is open on a wide viewport. */
 19	:root {
 20	  /* Pre-hydration fallback only; MUST equal DEFAULT_WORKSPACE_W in
 21	     workspace.rs — Rust owns the live value via an inline --workspace-w
 22	     property on <html> (set as the derived pane width changes). */
 23	  --workspace-w: 520px;
 24	  /* Readable content rail: transcript turns + composer share this centered
 25	     column when the pane stretches the shell (desktop split view). */
 26	  --workspace-rail: 860px;
 27	}
 28	
 29	/* ── Shell ─────────────────────────────────────────────────────────── */
 30	
 31	.workspace {
 32	  position: fixed;
 33	  top: 0;
 34	  right: 0;
 35	  bottom: 0;
 36	  width: var(--workspace-w);
 37	  display: flex;
 38	  flex-direction: column;
 39	  background: var(--sheen-soft), var(--bg-raised);
 40	  box-shadow: var(--elev-3);
 41	  z-index: 50;
 42	  transform: translateX(0);
 43	  transition: transform var(--dur) var(--ease-tide);
 44	}
 45	
 46	/* Collapsed: slide fully off the right edge and drop out of hit-testing.
 47	   The app shell removes the layout gutter (has-workspace-open) in lockstep. */
 48	.workspace.is-collapsed {
 49	  transform: translateX(100%);
 50	  pointer-events: none;
 51	}
 52	
 53	/* Wide viewport: the pane SPLITS the surface. The shell stops centering as a
 54	   1120px card in the FULL viewport (that model stranded its centering margin
 55	   as a dead strip between the column and the fixed-right pane) and instead
 56	   fills the remaining viewport, minus the pane gutter. Content rides a
 57	   readable centered rail inside; the header spans the full remaining width
 58	   like real app chrome. Below 900px the pane OVERLAYS instead (no gutter),
 59	   mirroring compact.css's narrow-column behavior. */
 60	@media (min-width: 900px) {
 61	  .ocean-surface.has-workspace-open {
 62	    max-width: none;
 63	    padding-right: var(--workspace-w);
 64	  }
 65	  .ocean-surface.has-workspace-open .transcript > *,
 66	  .ocean-surface.has-workspace-open .ocean-perms {
 67	    width: 100%;
 68	    max-width: var(--workspace-rail);
 69	    margin-inline: auto;
 70	  }
 71	  .ocean-surface.has-workspace-open .ocean-composer {
 72	    width: min(var(--workspace-rail), calc(100% - 36px));
 73	    margin-inline: auto;
 74	  }
 75	}
 76	
 77	/* Smooth the gutter as the pane collapses/expands. Scoped to padding-right so
 78	   it never interferes with other layout transitions on the shell. */
 79	.ocean-surface {
 80	  transition: padding-right var(--dur) var(--ease-tide);
 81	}
 82	
 83	/* During drag-resize the pointer moves the pane instantly; animating the
 84	   shell gutter behind it reads as rubber-band churn. Suppress all layout
 85	   transitions for the duration of the gesture. */
 86	html.is-resizing .ocean-surface,
 87	html.is-resizing .workspace {
 88	  transition: none;
 89	}
 90	html.is-resizing {
 91	  cursor: col-resize;
 92	  user-select: none;
 93	  -webkit-user-select: none;
 94	}
 95	
430	  background: var(--bg-hover);
431	  border-color: var(--border);
432	}
433	
434	/* ── Reduced motion ────────────────────────────────────────────────── */
435	
436	@media (prefers-reduced-motion: reduce) {
437	  .workspace,
438	  .ocean-surface {
439	    transition: none;
440	  }
