--- palette component ---
   235	///
   236	/// | Key          | Action                                      |
   237	/// |-------------|---------------------------------------------|
   238	/// | ⌘K / Ctrl+K | Open palette, focus input, reset query      |
   239	/// | Esc          | Close palette                               |
   240	/// | ↑ / ↓        | Move selection (wraps)                       |
   241	/// | Enter        | Run selected command, close palette          |
   242	/// | Backdrop     | click closes palette                         |
   243	#[component]
   244	pub fn PaletteView(registry: CommandRegistry, open: RwSignal<bool>) -> impl IntoView {
   245	    let query = RwSignal::new(String::new());
   246	    let selected_index = RwSignal::new(0usize);
   247	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
   248	
   249	    // ── Window-level keydown: Cmd+K / Ctrl+K opens the palette ──────────
   250	    let _key_listener = window_event_listener(ev::keydown, move |e: KeyboardEvent| {
   251	        // metaKey on macOS, ctrlKey elsewhere. We check both so Cmd+K works
   252	        // on Mac and Ctrl+K works everywhere else.
   253	        if !e.is_composing()
   254	            && (e.meta_key() || e.ctrl_key())
   255	            && !e.shift_key()
   256	            && !e.alt_key()
   257	            && e.key().eq_ignore_ascii_case("k")
   258	        {
   259	            e.prevent_default();
   260	            query.set(String::new());
   261	            selected_index.set(0);
   262	            open.set(true);
   263	        }
   264	    });
   265	    on_cleanup(move || _key_listener.remove());
   266	
   267	    // ── Auto-focus the input when the palette opens ──────────────────────
   268	    Effect::new(move |_| {
   269	        if open.get() {
   270	            request_animation_frame(move || {
   271	                if let Some(el) = input_ref.get() {
   272	                    let _ = el.focus();
   273	                    el.select();
   274	                }
   275	            });
   276	        }
   277	    });
   278	
   279	    // ── Filter + group + score ───────────────────────────────────────────
   280	    // Re-derived every time `query` or `registry.commands` changes.
   281	    let filtered_groups: Memo<Vec<(CommandScope, Vec<ScoredCommand>)>> = Memo::new(move |_| {
   282	        let q = query.get();
   283	        let q = q.trim();
   284	        let cmds = registry.commands.get();
   285	
   286	        let mut groups: Vec<(CommandScope, Vec<ScoredCommand>)> = Vec::new();
   287	
   288	        for cmd in cmds.iter() {
   289	            // Host/state gating: disabled commands are invisible.
   290	            if !cmd.enabled.get() {
   291	                continue;
   292	            }
   293	
   294	            let score = if q.is_empty() {
   295	                0.0
   296	            } else {
   297	                match fuzzy_score(q, &cmd.title) {
   298	                    Some(s) => s,
   299	                    None => continue, // no match → hidden
   300	                }
   301	            };
   302	
   303	            let group = groups.iter_mut().find(|(s, _)| *s == cmd.scope);
   304	            if let Some((_, cmds)) = group {
   305	                cmds.push(ScoredCommand {
   306	                    command: cmd.clone(),
   307	                    score,
   308	                });
   309	            } else {
   310	                groups.push((
   311	                    cmd.scope,
   312	                    vec![ScoredCommand {
   313	                        command: cmd.clone(),
   314	                        score,
   315	                    }],
   316	                ));
   317	            }
   318	        }
   319	
   320	        // Sort within each group by score descending (best first).
   321	        for (_, cmds) in groups.iter_mut() {
   322	            cmds.sort_by(|a, b| {
   323	                b.score
   324	                    .partial_cmp(&a.score)
   325	                    .unwrap_or(std::cmp::Ordering::Equal)
   326	            });
   327	        }
   328	
   329	        // Sort groups by scope order.
   330	        groups.sort_by_key(|(s, _)| s.order());
   331	
   332	        groups
   333	    });
   334	
   335	    // ── Flat list for index-based navigation ─────────────────────────────
   336	    let flat_commands: Memo<Vec<ScoredCommand>> = Memo::new(move |_| {
   337	        filtered_groups
   338	            .get()
   339	            .into_iter()
   340	            .flat_map(|(_, cmds)| cmds)
   341	            .collect()
   342	    });
   343	
   344	    let total_count = move || flat_commands.get().len();
   345	
   346	    // ── Keyboard navigation inside the palette ───────────────────────────
   347	    let on_input_keydown = move |ev: KeyboardEvent| {
   348	        if ev.is_composing() {
   349	            return;
   350	        }
   351	        match ev.key().as_str() {
   352	            "Escape" => {
   353	                ev.prevent_default();
   354	                ev.stop_propagation();
   355	                open.set(false);
   356	            }
   357	            "ArrowDown" => {
   358	                ev.prevent_default();
   359	                selected_index.update(|i| *i = next_index(*i, total_count()));
   360	            }
   361	            "ArrowUp" => {
   362	                ev.prevent_default();
   363	                selected_index.update(|i| *i = prev_index(*i, total_count()));
   364	            }
   365	            "Enter" => {
   366	                ev.prevent_default();
   367	                let idx = selected_index.get_untracked();
   368	                let cmds = flat_commands.get_untracked();
   369	                if let Some(sc) = cmds.get(idx) {
   370	                    sc.command.run.run(());
   371	                    open.set(false);
   372	                }
   373	            }
   374	            _ => {}
   375	        }
   376	    };
   377	
   378	    // ── View ─────────────────────────────────────────────────────────────
   379	    view! {
   380	        <Show when=move || open.get()>
   381	            // Backdrop — clicking outside the panel closes the palette.
   382	            <div class="palette-overlay" on:click=move |_| open.set(false)>
   383	                // Panel — stop propagation so clicks inside don't close.
   384	                <div class="palette-panel" on:click=|ev| ev.stop_propagation()>
   385	                    <input
   386	                        class="palette-input"
   387	                        type="text"
   388	                        placeholder="Type a command…"
   389	                        node_ref=input_ref
   390	                        prop:value=move || query.get()
   391	                        on:input=move |ev| {
   392	                            query.set(event_target_value(&ev));
   393	                            selected_index.set(0);
   394	                        }
   395	                        on:keydown=on_input_keydown
   396	                    />
   397	
   398	                    <div class="palette-results">
   399	                        <Show
   400	                            when=move || !flat_commands.get().is_empty()
   401	                            fallback=move || view! {
   402	                                <div class="palette-empty">
   403	                                    {move || {
   404	                                        if query.get().trim().is_empty() {
   405	                                            "No commands available"
   406	                                        } else {
   407	                                            "No matching commands"
   408	                                        }
   409	                                    }}
   410	                                </div>
   411	                            }
   412	                        >
   413	                            <For
   414	                                each=move || filtered_groups.get()
   415	                                key=|(scope, _)| *scope as usize
   416	                                children=move |(scope, cmds)| {
   417	                                    // Compute global index of each command in the
   418	                                    // flat list so we can check selection state.
   419	                                    let flat = flat_commands.get();
   420	                                    view! {
   421	                                        <div class="palette-group">
   422	                                            <div class="palette-group-label">
   423	                                                {scope.label()}
   424	                                            </div>
   425	                                            {
   426	                                                cmds.into_iter().map(|sc| {
   427	                                                    let cmd_id = sc.command.id;
   428	                                                    let global_idx = flat.iter()
   429	                                                        .position(|f| f.command.id == cmd_id)
   430	                                                        .unwrap_or(0);
   431	                                                    let is_selected = move || {
   432	                                                        selected_index.get() == global_idx
   433	                                                    };
   434	                                                    let run = sc.command.run;
   435	                                                    view! {
   436	                                                        <div
   437	                                                            class="palette-row"
   438	                                                            class:palette-row--selected=is_selected
   439	                                                            on:click=move |_| {
   440	                                                                run.run(());
   441	                                                                open.set(false);
   442	                                                            }
   443	                                                        >
   444	                                                            <span class="palette-row-title">
   445	                                                                {sc.command.title}
   446	                                                            </span>
   447	                                                            {if let Some(hint) = sc.command.hint {
   448	                                                                view! {
   449	                                                                    <span class="palette-row-hint">
   450	                                                                        {hint}
   451	                                                                    </span>
   452	                                                                }.into_any()
   453	                                                            } else {
   454	                                                                ().into_any()
   455	                                                            }}
   456	                                                            <span class="palette-row-kbd">"↵"</span>
   457	                                                        </div>
   458	                                                    }
   459	                                                }).collect::<Vec<_>>()
   460	                                            }
   461	                                        </div>
   462	                                    }
   463	                                }
   464	                            />
   465	                        </Show>
   466	                    </div>
   467	                </div>
   468	            </div>
   469	        </Show>
   470	    }
   471	}
   472	
   473	// ── Tests ──────────────────────────────────────────────────────────────────
   474	
   475	#[cfg(test)]
   476	mod tests {
   477	    use super::*;
   478	
   479	    // ── selection helpers ────────────────────────────────────────────────
   480	
   481	    #[test]
   482	    fn next_index_wraps_around() {
   483	        assert_eq!(next_index(0, 3), 1);
   484	        assert_eq!(next_index(1, 3), 2);
   485	        assert_eq!(next_index(2, 3), 0);
   486	    }
   487	
   488	    #[test]
   489	    fn prev_index_wraps_around() {
